def do_POST(self) -> None:  # noqa: N802 (BaseHTTPRequestHandler API)
    try:
        parsed = urlparse(self.path)
        path = parsed.path.rstrip("/") or "/"
        parsed_query = parsed.query
        if not path.startswith("/v1"):
            self._send_error(404, f"无此路径: {path}")
            return
        # 凭证状态回执消费（单条与批量）及凭证状态回执消费同步
        # 进度回执消费协议：显式空 X-Tenant-ID 一律 400 且仅
        # {"error": "请求非法"}（区别于其余入口的
        # “X-Tenant-ID 不能为空”）。
        if (
            path
            in (
                "/v1/trust/credential-status/receipt/consume",
                "/v1/trust/credential-status/receipt/consume-batch",
                "/v1/trust/credential-status/receipt-sync"
                "/receipt/consume",
                "/v1/trust/credential-status/receipt-sync"
                "/receipt/consume-batch",
                "/v1/trust/credentials/imported/verify-batch",
                "/v1/audit/manifest/verify-batch",
            )
            and self.headers.get("X-Tenant-ID") == ""
        ):
            raise ValidationError("请求非法")
        tenant = self._tenant_id()
        if path == "/v1/dids":
            self._post_dids(tenant)
        elif path == "/v1/dids/rotation-proofs/verify":
            self._post_rotation_proofs_verify(tenant)
        elif path == "/v1/audit/manifest/verify":
            self._post_audit_manifest_verify(tenant)
        elif path == "/v1/audit/manifest/verify-batch":
            self._post_audit_manifest_verify_batch(tenant)
        elif path == "/v1/credentials":
            self._post_credentials(tenant)
        elif path == "/v1/credential-schemas":
            self._post_credential_schemas(tenant)
        elif path.startswith("/v1/credential-schemas/") and path.endswith(
            "/status"
        ):
            self._post_credential_schema_status(
                tenant,
                path[
                    len("/v1/credential-schemas/") : -len("/status")
                ],
            )
        elif path == "/v1/credentials/status-export":
            self._post_credentials_status_export(tenant)
        elif path == "/v1/credentials/revoke-batch":
            self._post_revoke_credentials_batch(tenant)
        elif path.startswith("/v1/dids/") and path.endswith(
            "/keys/rotate"
        ):
            did = unquote(
                path[len("/v1/dids/") : -len("/keys/rotate")]
            )
            self._post_rotate_key(tenant, did)
        elif path.startswith("/v1/dids/") and "/keys/" in path and path.endswith(
            "/revoke"
        ):
            middle = path[len("/v1/dids/") : -len("/revoke")]
            did_raw, sep, version_raw = middle.partition("/keys/")
            did = unquote(did_raw)
            key_version = unquote(version_raw) if sep else ""
            self._post_revoke_key(tenant, did, key_version)
        elif path.startswith("/v1/dids/") and path.endswith(
            "/deactivate"
        ):
            did = unquote(
                path[len("/v1/dids/") : -len("/deactivate")]
            )
            self._post_deactivate_did(tenant, did)
        elif path.startswith("/v1/credentials/") and path.endswith(
            "/revoke"
        ):
            credential_id = unquote(
                path[len("/v1/credentials/") : -len("/revoke")]
            )
            self._post_revoke_credential(tenant, credential_id)
        elif path.startswith("/v1/credentials/") and path.endswith(
            "/verify"
        ):
            credential_id = unquote(
                path[len("/v1/credentials/") : -len("/verify")]
            )
            self._post_verify_credential(
                tenant, credential_id
            )
        elif path.startswith("/v1/credentials/") and path.endswith(
            "/present"
        ):
            credential_id = unquote(
                path[len("/v1/credentials/") : -len("/present")]
            )
            self._post_present(tenant, credential_id)
        elif path.startswith("/v1/credentials/") and path.endswith(
            "/present-batch"
        ):
            credential_id = unquote(
                path[len("/v1/credentials/") : -len("/present-batch")]
            )
            self._post_present_batch(tenant, credential_id)
        elif path.startswith("/v1/credentials/") and path.endswith(
            "/prove"
        ):
            credential_id = unquote(
                path[len("/v1/credentials/") : -len("/prove")]

def _post_credentials(self, tenant: str) -> None:
    # 可选 Idempotency-Key：租户头（路由层）、键格式与 JSON 对象
    # 格式的校验先于重放判定；未提供该头时完全按既有规则签发。
    idem_key = self._idempotency_key()
    data = self._read_json()
    idem_digest = None
    if idem_key is not None:
        idem_digest = _idempotent_request_digest(data)
        # 重放判定先于签发字段校验：同内容返回首次结果（200，
        # 不重新签名、不新增凭证或审计事件），异内容统一 409
        # （ConflictError 由路由映射），均不覆盖首次绑定。
        replay = store.idempotent_replay(tenant, idem_key, idem_digest)
        if replay is not None:
            self._send_json(
                200, self._credential_issue_payload(replay)
            )
            return
    self._require_fields(data, ("issuer_did", "subject_did"))
    if "claims" not in data:
        raise ValidationError("缺少字段: claims")
    if not isinstance(data["claims"], dict):
        raise ValidationError("字段 claims 必须为 JSON 对象")
    # expires_at 可选：提供时必须为 UTC 秒精度 Z 格式且严格晚于
    # 当前时刻（否则 400）；未提供传哨兵，正文不注入该字段，
    # 凭证保持无期限。
    expires_at = (
        data["expires_at"] if "expires_at" in data else EXPIRES_AT_UNSET
    )
    # schema_id/schema_version 可选，但必须同时出现或同时省略，
    # 否则 400；类型校验在 store 内完成。
    has_schema_id = "schema_id" in data
    has_schema_version = "schema_version" in data
    if has_schema_id != has_schema_version:
        raise ValidationError(
            "schema_id 与 schema_version 必须同时出现或同时省略"
        )
    created = True
    try:
        if idem_key is not None:
            # 只有成功签发才占用键；失败可按同键提交修正请求。
            record, created = store.create_credential_idempotent(
                tenant,
                idem_key,
                idem_digest,
                data["issuer_did"],
                data["subject_did"],
                data["claims"],
                expires_at=expires_at,
                schema_id=(
                    data["schema_id"] if has_schema_id else None
                ),
                schema_version=(
                    data["schema_version"] if has_schema_version else None
                ),
            )
        else:
            record = store.create_credential(
                tenant,
                data["issuer_did"],
                data["subject_did"],
                data["claims"],
                expires_at=expires_at,
                schema_id=(
                    data["schema_id"] if has_schema_id else None
                ),
                schema_version=(
                    data["schema_version"] if has_schema_version else None
                ),
            )
    except SchemaUnavailableError:
        # 显式引用已弃用/吊销模式版本：统一固定 409 原因，不签发、
        # 不写入、不记审计；未引用或引用 active 版本时走既有路径。
        self._send_json(
            409, {"error": "credential schema unavailable"}
        )
        return
    self._send_json(
        201 if created else 200,
        self._credential_issue_payload(record),
    )

@staticmethod
def _schema_payload(record: Any) -> Dict[str, Any]:
    """模式注册/读取成功响应的固定键序负载。"""
    return {
        "schema_id": record.schema_id,
        "version": record.version,
        "issuer_did": record.issuer_did,
        "claim_types": record.claim_types,
        "required_claims": record.required_claims,
        "digest": record.digest,
    }

def _post_credential_schemas(self, tenant: str) -> None:
    # POST /v1/credential-schemas：注册凭证模式约束。请求体恰含
    # schema_id（小写字母开头、小写字母/数字/下划线/连字符、
    # 1..64）、version（正整数）、issuer_did（同租户活动 DID）、
    # claim_types（1..100 个 RFC6901 路径 -> 六类 JSON 类型）、
    # required_claims（其键的不重复子集）。内容非法 400；issuer
    # 未知或跨租户 404；均不写入、不审计。同内容重复注册 200
    # 返回原记录，异内容 409；首次成功 201 并审计。
    data = self._read_json()
    required = (
        "schema_id", "version", "issuer_did",
        "claim_types", "required_claims",
    )
    missing = [field for field in required if field not in data]
    if missing:
        raise ValidationError(f"缺少字段: {', '.join(missing)}")
    extra = sorted(set(data) - set(required))
    if extra:
        raise ValidationError(f"多余字段: {', '.join(extra)}")
    record, created = store.register_credential_schema(
        tenant,
        data["schema_id"],
        data["version"],
        data["issuer_did"],
        data["claim_types"],
        data["required_claims"],
    )
    self._send_json(
        201 if created else 200, self._schema_payload(record)
    )

def _get_credential_schema(
    self, tenant: str, suffix: str, query: str
) -> None:
    # GET /v1/credential-schemas/{schema_id}/{version}
    # ?issuer_did=...：路径段非法（schema_id 格式、version 非
    # ASCII 正整数、段数不对）400；issuer_did 须唯一且非空，
    # 缺失/重复/空值 400；命中 200，模式缺失或跨租户 404
    # （存在性不可探测）。纯只读、不记审计。
    raw_segments = suffix.split("/")
    if len(raw_segments) != 2:
        raise ValidationError(
            "路径必须为 /v1/credential-schemas/{schema_id}/{version}"
        )
    schema_id = unquote(raw_segments[0])
    version_raw = unquote(raw_segments[1])
    if not schema_id or not SCHEMA_ID_RE.fullmatch(schema_id):
        raise ValidationError("路径参数 schema_id 非法")
    if (
        not version_raw
        or any(ch < "0" or ch > "9" for ch in version_raw)
        or int(version_raw) < 1
    ):
        raise ValidationError(
            "路径参数 version 必须为 ASCII 十进制正整数"
        )
    params = parse_qs(query, keep_blank_values=True)
    issuer_values = params.get("issuer_did")
    if issuer_values is None:
        raise ValidationError("查询参数 issuer_did 必填")
    if len(issuer_values) != 1:
        raise ValidationError("查询参数 issuer_did 只能提供一次")
    issuer_did = issuer_values[0]
    if not issuer_did:
        raise ValidationError(
            "查询参数 issuer_did 必须为非空字符串"
        )
    unknown = sorted(set(params) - {"issuer_did"})
    if unknown:
        raise ValidationError(
            f"不支持的查询参数: {', '.join(unknown)}"
        )
    record = store.get_credential_schema(
        tenant, schema_id, int(version_raw), issuer_did
    )
    self._send_json(200, self._schema_payload(record))

@staticmethod
def _parse_schema_version_suffix(suffix: str) -> Tuple[str, int]:
    """解析 {schema_id}/{version} 路径段，非法抛 ValidationError。"""
    raw_segments = suffix.split("/")
    if len(raw_segments) != 2:
        raise ValidationError(
            "路径必须为 "
            "/v1/credential-schemas/{schema_id}/{version}"
        )
    schema_id = unquote(raw_segments[0])
    version_raw = unquote(raw_segments[1])
    if not schema_id or not SCHEMA_ID_RE.fullmatch(schema_id):
        raise ValidationError("路径参数 schema_id 非法")
    if (
        not version_raw
        or any(ch < "0" or ch > "9" for ch in version_raw)
        or int(version_raw) < 1
    ):
        raise ValidationError(
            "路径参数 version 必须为 ASCII 十进制正整数"
        )
    return schema_id, int(version_raw)

@staticmethod
def _schema_status_payload(record: Any) -> Dict[str, Any]:
    """模式版本状态成功响应的固定键序负载。"""
    return {
        "schema_id": record.schema_id,
        "version": record.version,
        "issuer_did": record.issuer_did,
        "status": record.status,
        "reason": record.reason,
        "updated_at": record.updated_at,
    }

def _post_credential_schema_status(
    self, tenant: str, suffix: str
) -> None:
    # POST /v1/credential-schemas/{schema_id}/{version}/status：
    # 变更模式版本生命周期。请求体恰含 issuer_did、status 与可选
    # reason；status 仅接受 deprecated 或 revoked；reason 缺省
    # 取固定中文缺省值，显式值须为裁剪后非空字符串；其余格式问题
    # 一律 400。deprecated 仅可由 active 进入，revoked 可由
    # active/deprecated 进入，均不可恢复。首次变更 201；同目标
    # 状态且同 reason 的重复请求幂等 200（不追加历史/审计）；
    # reason 变化或逆向/越级转换 409；未知版本与跨租户访问 404。
    schema_id, version = self._parse_schema_version_suffix(suffix)
    data = self._read_json()
    required = ("issuer_did", "status")
    missing = [field for field in required if field not in data]
    if missing:
        raise ValidationError(f"缺少字段: {', '.join(missing)}")
    extra = sorted(set(data) - {"issuer_did", "status", "reason"})
    if extra:
        raise ValidationError(f"多余字段: {', '.join(extra)}")
    issuer_did = data["issuer_did"]
    if not isinstance(issuer_did, str) or not issuer_did:
        raise ValidationError(
            "字段 issuer_did 必须为非空字符串"
        )
    target_status = data["status"]
    if target_status not in ("deprecated", "revoked"):
        raise ValidationError(
            "字段 status 只能为 deprecated 或 revoked"
        )
    if "reason" in data:
        reason = data["reason"]
        if not isinstance(reason, str) or not reason.strip():
            raise ValidationError(
                "字段 reason 必须为裁剪后非空字符串"
            )
    else:
        reason = REASON_UNSET
    record, created = store.set_credential_schema_status(
        tenant, schema_id, version, issuer_did, target_status, reason
    )
    self._send_json(
        201 if created else 200,
        self._schema_status_payload(record),
    )

def _get_credential_schema_status(
    self, tenant: str, suffix: str, query: str
) -> None:
    # GET /v1/credential-schemas/{schema_id}/{version}/status
    # ?issuer_did=...：只读模式版本生命周期状态。路径与
    # issuer_did 参数规则同 GET 模式（段数/格式非法、issuer_did
    # 缺失/重复/空值/其他参数 400）；未知版本与跨租户 404。
    # active 返 reason/updated_at 均 null。纯只读、不记审计。
    schema_id, version = self._parse_schema_version_suffix(suffix)
    params = parse_qs(query, keep_blank_values=True)
    issuer_values = params.get("issuer_did")
    if issuer_values is None:
        raise ValidationError("查询参数 issuer_did 必填")
    if len(issuer_values) != 1:
        raise ValidationError("查询参数 issuer_did 只能提供一次")
    issuer_did = issuer_values[0]
    if not issuer_did:
        raise ValidationError(
