        )
    record = store.get_credential_schema_status(
        tenant, schema_id, version, issuer_did
    )
    self._send_json(
        200, self._schema_status_payload(record)
    )

def _get_credential_schema_history(
    self, tenant: str, suffix: str, query: str
) -> None:
    # GET /v1/credential-schemas/{schema_id}/{version}/history
    # ?issuer_did=...&limit=&after=：只读模式版本生命周期历史，
    # 按 cursor 升序分页。issuer_did 须唯一非空；limit 缺省 50、
    # 限 1..200；after 缺省 0、须非负 ASCII 十进制整数；重复/
    # 空白/符号/小数/未知参数均 400；路径段非法 400；未知版本
    # 与跨租户 404。响应恰含 schema_id、version、issuer_did、
    # events、next_after；事件恰含 action、status、reason、
    # updated_at、audit_seq、audit_timestamp、cursor（注册事件
    # reason 为 null）；空页 next_after 保持 after。纯只读。
    schema_id, version = self._parse_schema_version_suffix(suffix)
    params = parse_qs(query, keep_blank_values=True)
    issuer_values = params.get("issuer_did")
    if issuer_values is None:
        raise ValidationError("查询参数 issuer_did 必填")
    if len(issuer_values) != 1:
        raise ValidationError("查询参数 issuer_did 只能提供一次")
    issuer_did = issuer_values[0]
    if not issuer_did:
        raise ValidationError(
            "查询参数 issuer_did 必须为非空字符串"
        )
    unknown = sorted(set(params) - {"issuer_did", "limit", "after"})
    if unknown:
        raise ValidationError(
            f"不支持的查询参数: {', '.join(unknown)}"
        )
    limit_values = params.get("limit")
    if limit_values is not None:
        if len(limit_values) != 1:
            raise ValidationError("查询参数 limit 只能提供一次")
        limit = _parse_nonneg_int(limit_values[0], "limit")
        if not 1 <= limit <= 200:
            raise ValidationError(
                "查询参数 limit 须在 1 到 200 之间"
            )
    else:
        limit = 50
    after_values = params.get("after")
    if after_values is not None:
        if len(after_values) != 1:
            raise ValidationError("查询参数 after 只能提供一次")
        after = _parse_nonneg_int(after_values[0], "after")
    else:
        after = 0
    events, next_after = store.list_credential_schema_history(
        tenant, schema_id, version, issuer_did, after, limit
    )
    self._send_json(
        200,
        {
            "schema_id": schema_id,
            "version": version,
            "issuer_did": issuer_did,
            "events": [
                {
                    "action": event.action,
                    "status": event.status,
                    "reason": event.reason,
                    "updated_at": event.updated_at,
                    "audit_seq": event.audit_seq,
                    "audit_timestamp": event.audit_timestamp,
                    "cursor": event.cursor,
                }
                for event in events
            ],
            "next_after": next_after,
        },
    )

def _post_credentials_status_export(self, tenant: str) -> None:
    # POST /v1/credentials/status-export：新增凭证状态签名发布。
    # 请求体恰为 {"credential_ids": [字符串...]}，数组 1..100 项，
    # 值非空且不重复；结构、类型或数量非法一律 400 且恰返
    # {"error":"请求非法"}。租户头沿用既有缺省、空值与隔离规则。

def _post_revoke_credentials_batch(self, tenant: str) -> None:
    # POST /v1/credentials/revoke-batch：整批原子吊销。
    # 请求体须恰为 {"items": [项...]}，items 为 1..100 个对象；
    # 每项恰含 credential_id（必填非空字符串，批内不重复）与可
    # 选 reason（省略走默认原因“持证人主动吊销”，提供时须为字
    # 符串且首尾裁剪后非空）。空体、非法 JSON、非对象、外层缺
    # 字段或多余字段、items 非数组/空/超限、项缺字段/多余字段/
    # 类型错误、credential_id 缺失或为空或批内重复、reason 非法
    # 均 400 且非空 error；任一凭证未知或属他租户 404；显式空
    # X-Tenant-ID 400。请求级与资源级错误均整批不落盘。成功
    # 200 仅返 {"results": [...]}，与输入等长同序，每项沿用单
    # 张吊销结果键序 credential_id、status、reason、revoked_at、
    # updated_at；已吊销项保持首次 reason/revoked_at。全部状态、
    # 历史、游标与审计同一次原子写，失败 500 整体回滚。
    data = self._read_json()
    if set(data) != {"items"}:
        missing = "items" if "items" not in data else None
        if missing is not None:
            raise ValidationError("缺少字段: items")
        extra = ", ".join(sorted(set(data) - {"items"}))
        raise ValidationError(f"多余字段: {extra}")
    items = data["items"]
    if not isinstance(items, list):
        raise ValidationError("字段 items 必须为数组")
    if not 1 <= len(items) <= 100:
        raise ValidationError(
            "字段 items 须包含 1 到 100 个请求项"
        )
    parsed_items: List[Tuple[str, Any]] = []
    seen: set[str] = set()
    for index, item in enumerate(items):
        prefix = f"items[{index}]"
        if not isinstance(item, dict):
            raise ValidationError(f"{prefix} 必须为 JSON 对象")
        allowed = {"credential_id", "reason"}
        unknown = sorted(set(item) - allowed)
        if unknown:
            raise ValidationError(
                f"{prefix} 多余字段: {', '.join(unknown)}"
            )
        if "credential_id" not in item:
            raise ValidationError(
                f"{prefix} 缺少字段: credential_id"
            )
        credential_id = item["credential_id"]
        if not isinstance(credential_id, str) or not credential_id:
            raise ValidationError(
                f"{prefix} 字段 credential_id 必须为非空字符串"
            )
        if credential_id in seen:
            raise ValidationError(
                f"{prefix} credential_id 批内重复: "
                f"{credential_id}"
            )
        seen.add(credential_id)
        reason: Any = REASON_UNSET
        if "reason" in item:
            reason = item["reason"]
            if not isinstance(reason, str):
                raise ValidationError(
                    f"{prefix} 字段 reason 必须为字符串"
                )
